let page='dashboard',callback=null,opener=null;
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
try{document.documentElement.dataset.theme=localStorage.getItem('cf-prototype-theme')||'light'}catch{}
function syncTheme(){const dark=document.documentElement.dataset.theme==='dark';$('#theme').textContent=dark?'Chế độ sáng':'Chế độ tối';$('#theme').setAttribute('aria-pressed',String(dark))}
$('#menu').onclick=()=>{const open=$('#page-nav').classList.toggle('open');$('#menu').setAttribute('aria-expanded',String(open))};syncTheme();$('#theme').onclick=()=>{document.documentElement.dataset.theme=document.documentElement.dataset.theme==='dark'?'light':'dark';try{localStorage.setItem('cf-prototype-theme',document.documentElement.dataset.theme)}catch{}syncTheme()};
