function modal(title,body,confirm,fn){opener=document.activeElement;$('#dialog-title').textContent=title;$('#dialog-body').innerHTML=body;$('#confirm').textContent=confirm;callback=fn;$('#dialog').returnValue='cancel';$('#dialog').showModal()}
$('#dialog').addEventListener('close',()=>{const fn=callback;const previous=opener;callback=null;if($('#dialog').returnValue==='confirm'&&fn)fn();if(!$('#dialog').open&&previous?.isConnected)previous.focus()});
