function dashboard(){return `<div class="page-head"><div><p class="eyebrow">Không gian học tập</p><h1>Tiếp tục hành trình của bạn.</h1><p class="subtitle">Mỗi bài thực hành là một bước tiến. Hôm nay, bắt đầu từ phần đang học.</p></div><span class="meta">Thứ Bảy, 10 tháng 10</span></div>${state.scenario==='empty'?empty('Bài học đầu tiên đang chờ bạn','Chọn một lộ trình để bắt đầu thực hành trên trình duyệt.','#path','Khám phá lộ trình'):session()+`<div class="grid"><div><section class="panel continue"><div class="between"><span class="meta">Đang học · Web Application Security</span><span class="meta">${state.solved?'4':'3'}/6 nhiệm vụ</span></div><h2>SQL Injection căn bản</h2><p class="meta">Hiểu cách dữ liệu đầu vào tác động đến truy vấn cơ sở dữ liệu.</p><div class="progress"><span style="width:${state.solved?67:50}%"></span></div><p class="meta">Tiếp theo: ${state.solved?'Truy vấn có tham số':'Nhận diện truy vấn không an toàn'}</p><div class="actions"><a class="button primary" href="#room">Tiếp tục học →</a><a class="button quiet" href="#path">Xem lộ trình</a></div></section><section class="section panel"><div class="between"><h2>Lộ trình của bạn</h2><span class="meta">2 lộ trình</span></div><div class="line"><div><h3>Web Application Security</h3><p class="meta">${state.solved?16:15}/36 nhiệm vụ bắt buộc · Trung cấp</p></div><a class="button quiet" href="#path">Xem →</a></div><div class="line"><div><h3>Pre-Security</h3><p class="meta">24/24 nhiệm vụ · Đã hoàn thành</p></div><button class="quiet" data-action="pres">Xem →</button></div></section><section class="section panel"><h2>Thành tích gần đây</h2><div class="line"><div><h3>Nền tảng Linux</h3><p class="meta">Hoàn thành 8 phòng thực hành · 08/10/2026</p></div><span class="good">Đã đạt</span></div></section></div><aside><section class="panel"><h2>Tiến độ cá nhân</h2><div class="stats"><div class="stat"><strong>12 <small class="meta">ngày</small></strong><span class="meta">Chuỗi học hiện tại</span></div><div class="stat"><strong>${state.solved?(state.hint?'2.540':'2.550'):'2.450'}</strong><span class="meta">Tổng EXP</span></div></div><p class="meta">Cấp bậc: Script Kiddie</p><p class="note">Hoàn thành một nhiệm vụ mới trước 23:59 để duy trì chuỗi học.<br>Asia/Ho_Chi_Minh</p></section><section class="section panel"><h2>Năng lực đã tích lũy</h2>${[['Web Security',850],['Network Pentesting',620],['Binary Exploitation',120],['Cryptography',200],['DFIR',180],['Windows & AD',140],['Blue Team / SOC',240],['Cloud & DevSecOps',100]].map(([n,v])=>`<div class="skill"><span>${n}</span><span>${v} EXP</span></div>`).join('')}<p class="meta" style="margin-top:14px">Điểm tích lũy theo từng kỹ năng.</p></section></aside></div>`}`}
function path(){return `<a class="back" href="#dashboard">← Tổng quan học tập</a><div class="page-head"><div><p class="eyebrow">Lộ trình / Bảo mật ứng dụng</p><h1>Web Application Security</h1><p class="subtitle">Từ cơ chế hoạt động của web đến phát hiện và xử lý lỗ hổng phổ biến.</p></div><a class="button primary" href="#room">Tiếp tục học →</a></div><div class="grid"><div><div class="between"><span>${state.solved?16:15}/36 nhiệm vụ bắt buộc</span><strong>${state.solved?44:42}%</strong></div><div class="progress"><span style="width:${state.solved?44:42}%"></span></div><section class="section"><h2>Nội dung lộ trình</h2><details class="module"><summary>01 · Nền tảng ứng dụng web <span>12/12 nhiệm vụ</span></summary><div class="line"><div>HTTP và trình duyệt<p class="meta">Đã hoàn thành · 6/6 nhiệm vụ</p></div><button data-action="review" class="quiet">Ôn tập</button></div><div class="line"><div>Cookies và phiên làm việc<p class="meta">Đã hoàn thành · 6/6 nhiệm vụ</p></div><button data-action="review" class="quiet">Ôn tập</button></div></details><details class="module" open><summary>02 · Khai thác và phòng chống injection <span>${state.solved?4:3}/12 nhiệm vụ</span></summary><div class="line"><div><h3>SQL Injection căn bản</h3><p class="meta">${state.solved?'4':'3'}/6 nhiệm vụ · 45 phút ước tính</p></div><a href="#room" class="button">Tiếp tục →</a></div><div class="line"><div><h3>Blind SQL Injection</h3><p class="meta">Cần hoàn thành SQL Injection căn bản.</p></div><button class="quiet" data-action="locked">Điều kiện</button></div></details><details class="module"><summary>03 · Xác thực và kiểm soát truy cập <span>0/12 nhiệm vụ</span></summary><p class="note">Hoàn thành module Injection để mở nội dung này.</p><div class="line">Kiểm soát quyền truy cập · 6 nhiệm vụ</div><div class="line">Bảo vệ phiên đăng nhập · 6 nhiệm vụ</div></details></section></div><aside class="panel"><h2>Về lộ trình</h2><div class="line"><span class="meta">Trình độ</span><span>Trung cấp</span></div><div class="line"><span class="meta">Thời lượng ước tính</span><span>18 giờ</span></div><div class="line"><span class="meta">Nội dung</span><span>3 module · 6 phòng</span></div><section class="section"><h3>Điều kiện dự thi</h3><p class="meta" style="margin-top:12px">Hoàn thành tất cả phòng bắt buộc để mở kỳ thi thực hành Capstone.</p><p class="note">Bạn đã hoàn thành 2/6 phòng bắt buộc.</p><button style="margin-top:20px" disabled>Chưa đủ điều kiện thi</button></section></aside></div>`}
const roomTasks = {
  practice: [
    {title:'Ứng dụng web và cơ sở dữ liệu', text:'Ứng dụng web lưu dữ liệu người dùng trong cơ sở dữ liệu. SQL là ngôn ngữ để đọc và cập nhật những dữ liệu này.', question:'Ngôn ngữ nào được dùng để truy vấn cơ sở dữ liệu quan hệ?', answer:'SQL'},
    {title:'Phạm vi thực hành an toàn', text:'Chỉ thực hành trên máy mục tiêu được cấp cho phiên lab. Không quét máy của người khác hoặc mạng Internet công cộng.', question:'Xác nhận bạn đã đọc phạm vi thực hành.', read:true},
    {title:'Khởi chạy môi trường lab', text:'Mở Điều khiển máy để xem trạng thái máy mục tiêu. Địa chỉ IP và thời gian còn lại được hiển thị phía trên vùng nhiệm vụ.', question:'Địa chỉ IP mẫu của máy mục tiêu là gì?', answer:'100.64.12.84'},
    {title:'Nhận diện truy vấn không an toàn', text:'Khi dữ liệu đầu vào được ghép trực tiếp vào câu lệnh SQL, ứng dụng có thể coi dữ liệu đó là một phần của truy vấn. Hãy quan sát ví dụ và tìm cách tách dữ liệu khỏi câu lệnh.', code:true, question:'Kỹ thuật nào giúp tránh ghép trực tiếp dữ liệu vào SQL?', answer:'prepared statements'},
    {title:'Truy vấn có tham số', text:'Truy vấn có tham số giữ cấu trúc câu lệnh tách biệt với dữ liệu người dùng. Giá trị đầu vào được truyền qua tham số thay vì nối vào chuỗi SQL.', question:'Dữ liệu đầu vào nên truyền qua thành phần nào?', answer:'tham số'},
    {title:'Tổng kết phòng học', text:'Bạn đã tìm hiểu vai trò của SQL, phạm vi thực hành và cách dùng truy vấn có tham số. Áp dụng nguyên tắc này khi đọc hoặc viết code xử lý dữ liệu.', question:'Xác nhận bạn đã đọc phần tổng kết.', read:true}
  ],
  theory: [
    {title:'Tư duy bảo mật', text:'Bảo mật bắt đầu từ việc hiểu hệ thống hoạt động như thế nào, dữ liệu nào cần được bảo vệ và điều gì có thể xảy ra khi một giả định không còn đúng. Phòng lý thuyết này không yêu cầu máy ảo.', question:'Xác nhận bạn đã đọc phần giới thiệu.', read:true},
    {title:'Ba thuộc tính của an toàn thông tin', text:'Tính bí mật giới hạn ai được xem dữ liệu. Tính toàn vẹn đảm bảo dữ liệu không bị thay đổi ngoài ý muốn. Tính sẵn sàng giúp người có quyền truy cập hệ thống khi cần.', question:'Thuộc tính nào bảo vệ dữ liệu khỏi thay đổi ngoài ý muốn?', answer:'tính toàn vẹn'},
    {title:'Nhận diện rủi ro', text:'Rủi ro cần được xem xét theo khả năng xảy ra và mức độ ảnh hưởng. Một lỗ hổng ít xuất hiện vẫn có thể quan trọng nếu ảnh hưởng đến dữ liệu hoặc dịch vụ thiết yếu.', question:'Xác nhận bạn đã đọc phần nhận diện rủi ro.', read:true},
    {title:'Nguyên tắc đặc quyền tối thiểu', text:'Mỗi người dùng và dịch vụ chỉ nên được cấp các quyền cần thiết để thực hiện công việc. Giảm quyền không cần thiết giúp giới hạn ảnh hưởng khi có sự cố.', question:'Nguyên tắc nào giới hạn quyền ở mức cần thiết?', answer:'đặc quyền tối thiểu'}
  ]
};
function taskKey(index) { return state.roomType + '-' + index; }
function taskDone(index) {
  const key = taskKey(index);
  return Boolean(state.taskSolved[key] || (state.roomType === 'practice' && (index < 3 || (index === 3 && state.solved))));
}
function taskMarkup(task, index) {
  const key = taskKey(index), done = taskDone(index), hinted = state.taskHints[key];
  const answer = state.taskAnswers[key] || '';
  return `<details class="task" data-task="${index}" ${state.taskOpen[state.roomType].includes(index + 1)?'open':''}>
    <summary><span class="task-number">Nhiệm vụ ${index + 1}</span><span class="task-title">${task.title}</span><span class="task-status ${done?'good':''}">${done?'Hoàn thành':'Chưa hoàn thành'}</span></summary>
    <div class="task-body"><p>${task.text}</p>
    ${task.code?`<pre class="code">SELECT * FROM users
WHERE username = '&quot; + username + &quot;'
AND password = '&quot; + password + &quot;';</pre><p>Thử quan sát dữ liệu đầu vào trong môi trường lab và xem cách câu lệnh thay đổi. Không thao tác trên hệ thống ngoài phạm vi được cấp.</p>`:''}
    <form class="task-question" data-question="${index}">
      <div class="between"><h3>${task.read?'Xác nhận nội dung':'Trả lời câu hỏi'}</h3><span class="meta">${hinted?90:100} EXP</span></div>
      ${task.read?`<p>${task.question}</p>`:`<label for="task-answer-${index}">${task.question}<input id="task-answer-${index}" data-answer="${index}" value="${escapeHTML(answer)}" autocomplete="off" aria-describedby="task-feedback-${index}" ${done?'disabled':''}></label><p class="meta">Đáp án thử prototype: ${task.answer}</p>`}
      <div class="actions"><button class="primary" ${done||state.scenario==='offline'?'disabled':''}>${done?'Đã hoàn thành':task.read?'Đã đọc và hiểu':'Kiểm tra đáp án'}</button>${!task.read?`<button type="button" class="quiet" data-task-hint="${index}" ${done||hinted||state.scenario==='offline'?'disabled':''}>Gợi ý · −10 EXP</button>`:''}</div>
      <div id="task-feedback-${index}" class="feedback ${done?'good':''}" role="status">${done?'Nhiệm vụ đã hoàn thành.':hinted?'Gợi ý: '+task.answer:''}</div>
    </form></div></details>`;
}
function room() {
  const theory = state.roomType === 'theory', tasks = roomTasks[state.roomType];
  const complete = tasks.filter((_, index) => taskDone(index)).length;
  return `<a class="back" href="#path">← Web Application Security</a>
    <div class="page-head"><div><p class="eyebrow">${theory?'Phòng lý thuyết':'Phòng thực hành'} / Bảo mật ứng dụng</p><h1>${theory?'Nền tảng an toàn thông tin':'SQL Injection căn bản'}</h1></div>
      <label class="room-type">Loại phòng mô phỏng<select id="room-type"><option value="practice" ${!theory?'selected':''}>Phòng thực hành</option><option value="theory" ${theory?'selected':''}>Phòng lý thuyết</option></select></label></div>
    <div class="room-progress"><span>${complete}/${tasks.length} nhiệm vụ đã hoàn thành</span><span class="meta">Mở từng nhiệm vụ để đọc và trả lời</span></div>
    ${!theory?`<div class="session"><span><strong>${state.running?'Máy đang chạy':'Máy đã dừng'}</strong> · <span class="mono">${state.running?'100.64.12.84 · '+(54+state.extensions*60)+':20':'Chưa có IP'}</span></span><div class="actions" style="margin:0"><button data-action="copy" ${!state.running?'disabled':''}>Chép IP</button><button data-action="machine">Điều khiển máy</button></div></div>
    <div class="mobile-tabs" role="tablist" aria-label="Vùng phòng học"><button role="tab" id="lesson-tab" aria-controls="lesson-panel" aria-selected="${state.tab==='lesson'}" class="${state.tab==='lesson'?'active':''}" data-tab="lesson">Bài học</button><button role="tab" id="practice-tab" aria-controls="practice-panel" aria-selected="${state.tab==='practice'}" class="${state.tab==='practice'?'active':''}" data-tab="practice">Thực hành</button></div>`:''}
    <div class="room-layout ${theory?'theory-only':''}" data-tab="${state.tab}">
      <section class="lesson task-list" id="lesson-panel" tabindex="0" aria-label="Danh sách nhiệm vụ có thể cuộn">${tasks.map(taskMarkup).join('')}</section>
      ${!theory?`<section class="practice" id="practice-panel" aria-label="Terminal mô phỏng"><div class="terminal"><div class="terminal-head"><span>Terminal · Môi trường mẫu</span><button data-action="terminal">Chạy lệnh mẫu</button></div><pre id="terminal-output">${state.scenario==='offline'?'Mất kết nối mô phỏng. Nội dung phiên được giữ.':!state.running?'Máy đã dừng. Mở điều khiển máy để khởi chạy.':'student@cyberforce:~$\n\nMôi trường thực hành đã sẵn sàng.\nTarget: 100.64.12.84\n\nChọn “Chạy lệnh mẫu” để xem phản hồi.\nKhông có lệnh nào được thực thi trên máy thật.'}</pre><div class="terminal-foot">Phiên mô phỏng · Không kết nối máy chủ lab</div></div></section>`:''}
    </div>`;
}
function bindTasks() {
  if (!$('#room-type')) return;
  $('#room-type').onchange = e => { state.roomType = e.target.value; render(); };
  const list = $('.task-list');
  const roomType = state.roomType;
  list.scrollTop = state.taskScroll[state.roomType];
  list.onscroll = () => { state.taskScroll[roomType] = list.scrollTop; };
  document.querySelectorAll('[data-task]').forEach(item => {
    item.ontoggle = () => {
      state.taskOpen[roomType] = Array.from(list.querySelectorAll('[data-task][open]'), el => Number(el.dataset.task) + 1);
    };
  });
  document.querySelectorAll('[data-answer]').forEach(input => {
    input.oninput = () => { state.taskAnswers[taskKey(Number(input.dataset.answer))] = input.value; };
  });
  document.querySelectorAll('[data-question]').forEach(form => {
    form.onsubmit = e => {
      e.preventDefault();
      if (state.scenario === 'offline') return;
      const index = Number(form.dataset.question), key = taskKey(index), task = roomTasks[state.roomType][index];
      const correct = task.read || (state.taskAnswers[key] || '').trim().toLocaleLowerCase('vi') === task.answer.toLocaleLowerCase('vi');
      if (!correct) {
        $('#task-feedback-' + index).textContent = 'Chưa đúng. Hãy xem lại nội dung hoặc mở gợi ý.';
        $('#task-answer-' + index).setAttribute('aria-invalid', 'true');
        return;
      }
      state.taskSolved[key] = true;
      if (state.roomType === 'practice' && index === 3) { state.solved = true; state.hint = Boolean(state.taskHints[key]); }
      render();
      $('#task-feedback-' + index).textContent = 'Đã hoàn thành · +' + (state.taskHints[key]?90:100) + ' EXP mô phỏng.';
    };
  });
  document.querySelectorAll('[data-task-hint]').forEach(button => {
    button.onclick = () => {
      const index = Number(button.dataset.taskHint), key = taskKey(index);
      modal('Mở gợi ý cho nhiệm vụ này?', '<p>Điểm tối đa của câu hỏi giảm từ 100 xuống 90 EXP. Cấp bậc của bạn được giữ nguyên.</p>', 'Mở gợi ý', () => { state.taskHints[key] = true; render(); });
    };
  });
}
function cms(){const rows=state.scenario==='empty'?[]:state.rooms.filter(r=>r.name.toLocaleLowerCase('vi').includes(state.search.toLocaleLowerCase('vi'))&&(state.filter==='all'||r.status===state.filter));return `<div class="page-head"><div><p class="eyebrow">Quản trị / Nội dung đào tạo</p><h1>Quản lý nội dung</h1><p class="subtitle">Soạn bài, kiểm tra chất lượng và xuất bản nội dung cho học viên.</p></div><button class="primary" data-action="new">Tạo phòng học</button></div><div class="cms-tabs" aria-label="Loại nội dung">${['Lộ trình','Module','Phòng'].map(t=>`<button class="${state.cmsType===t?'active':''}" data-type="${t}" aria-pressed="${state.cmsType===t}">${t}</button>`).join('')}</div>${state.cmsType!=='Phòng'?empty(state.cmsType+' trong prototype','Bản demo tập trung vào quản lý phòng học. Các mẫu cấu trúc khác nằm trong tài liệu wireframe.'): `<div class="toolbar"><label style="flex:1">Tìm phòng học<input id="search" type="search" placeholder="Tìm theo tên phòng…" value="${escapeHTML(state.search)}"></label><label>Trạng thái<select id="filter"><option value="all">Tất cả trạng thái</option>${['Bản nháp','Chờ duyệt','Đã xuất bản'].map(s=>`<option ${s===state.filter?'selected':''}>${s}</option>`).join('')}</select></label></div><div class="between" style="margin-bottom:16px"><span class="meta">${rows.length} phòng học</span><span class="meta">Dữ liệu mô phỏng</span></div>${rows.length?`<div class="table-wrap"><table><thead><tr><th scope="col">Phòng học</th><th scope="col">Lộ trình</th><th scope="col">Trạng thái</th><th scope="col">Nhiệm vụ</th><th scope="col">Thao tác</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${escapeHTML(r.name)}</td><td data-label="Lộ trình">${escapeHTML(r.path)}</td><td data-label="Trạng thái"><span class="${r.status==='Đã xuất bản'?'good':''}">${r.status}</span></td><td data-label="Nhiệm vụ">${r.tasks}</td><td><button class="quiet" data-edit="${state.rooms.indexOf(r)}" aria-label="Chỉnh sửa ${escapeHTML(r.name)}">Chỉnh sửa →</button></td></tr>`).join('')}</tbody></table></div>`:empty('Chưa có phòng học phù hợp','Thử đổi bộ lọc hoặc tạo một bản nháp mới.')}<p class="note">Nội dung chỉ xuất bản sau khi kiểm tra thông tin, câu hỏi và môi trường thực hành.</p>`}`}
function render(){page=location.hash.slice(1)||'dashboard';if(!['dashboard','path','room','cms'].includes(page))page='dashboard';$('#main').className=page==='room'?'room-page':'';$('#offline').hidden=state.scenario!=='offline';document.querySelectorAll('nav a').forEach(a=>{if(a.hash==='#'+page)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});$('#main').innerHTML=({dashboard,path,room,cms})[page]();$('#page-nav').classList.remove('open');$('#menu').setAttribute('aria-expanded','false');bind()}
function machine(){modal('Điều khiển máy',`<p>${state.running?'Máy mục tiêu đang chạy tại <code>100.64.12.84</code>.':'Máy hiện đã dừng.'}</p><p>Gia hạn đã dùng: ${state.extensions}/3. Mọi thao tác chỉ mô phỏng.</p><div class="actions"><button type="button" id="extend" ${state.extensions>=3||!state.running||state.scenario==='offline'?'disabled':''}>Gia hạn 60 phút</button><button type="button" id="stop" ${state.scenario==='offline'?'disabled':''}>${state.running?'Dừng máy':'Khởi chạy máy'}</button></div><p id="machine-msg" role="status"></p>`,'Đóng',()=>{});$('#extend').onclick=()=>{state.extensions++;$('#machine-msg').textContent='Đã gia hạn. Còn '+(3-state.extensions)+' lượt.';$('#extend').disabled=state.extensions>=3;render()};$('#stop').onclick=()=>{if(!state.running){state.running=true;state.extensions=0;$('#dialog').close();render();return}$('#dialog').close();setTimeout(()=>modal('Dừng máy mục tiêu?','<p>Dữ liệu trên máy mô phỏng sẽ bị xóa. Câu trả lời và tiến độ bài học vẫn được giữ.</p>','Dừng máy',()=>{state.running=false;render()}),0)}}
function edit(index){const r=index>=0?state.rooms[index]:null;modal(r?'Chỉnh sửa phòng học':'Tạo phòng học',`<label>Tên phòng<input id="edit-name" value="${escapeHTML(r?.name||'')}" required></label><label>Lộ trình<input id="edit-path" value="${escapeHTML(r?.path||'Web Application Security')}" required></label><label>Trạng thái<select id="edit-status"><option>Bản nháp</option><option ${r?.status==='Chờ duyệt'?'selected':''}>Chờ duyệt</option><option ${r?.status==='Đã xuất bản'?'selected':''}>Đã xuất bản</option></select></label><p class="meta">Chỉ sửa metadata mô phỏng. Chọn “Đã xuất bản” không đăng nội dung lên hệ thống.</p>`, 'Lưu mô phỏng',()=>{if(state.scenario==='offline'){modal('Chưa thể lưu','<p>Đang ở trạng thái mất kết nối mô phỏng. Hãy chuyển về bình thường và thử lại.</p>','Đóng',()=>{});return}const data={name:$('#edit-name').value.trim(),path:$('#edit-path').value.trim(),status:$('#edit-status').value,tasks:r?.tasks||0};if(!data.name||!data.path)return;if(r)state.rooms[index]=data;else state.rooms.unshift(data);render()});$('#confirm').disabled=state.scenario==='offline'}
function bind(){bindTasks();if($('#answer'))$('#answer').oninput=e=>state.answer=e.target.value;if($('#answer-form'))$('#answer-form').onsubmit=e=>{e.preventDefault();if(state.scenario==='offline')return;state.answer=$('#answer').value;if(state.answer.trim().toLowerCase()==='prepared statements'){state.solved=true;render()}else{$('#answer-feedback').textContent='Chưa đúng. Hãy thử “prepared statements” để kiểm tra trạng thái thành công.';$('#answer').setAttribute('aria-invalid','true')}};document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{state.tab=b.dataset.tab;$('.room-layout').dataset.tab=state.tab;document.querySelectorAll('[data-tab]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-selected',String(x===b))})});document.querySelectorAll('[data-tab]').forEach(b=>b.onkeydown=e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const next=e.key==='Home'?'lesson':e.key==='End'?'practice':b.dataset.tab==='lesson'?'practice':'lesson';document.querySelector('[data-tab="'+next+'"]').click();document.querySelector('[data-tab="'+next+'"]').focus()}});if($('#search'))$('#search').oninput=e=>{const pos=e.target.selectionStart;state.search=e.target.value;render();$('#search').focus();$('#search').setSelectionRange(pos,pos)};if($('#filter'))$('#filter').onchange=e=>{state.filter=e.target.value;render()};document.querySelectorAll('[data-type]').forEach(b=>b.onclick=()=>{state.cmsType=b.dataset.type;render()});document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>edit(Number(b.dataset.edit)));document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>{switch(b.dataset.action){case'machine':machine();break;case'copy':if(!navigator.clipboard){b.textContent='IP: 100.64.12.84';break}navigator.clipboard.writeText('100.64.12.84').then(()=>b.textContent='Đã chép',()=>b.textContent='IP: 100.64.12.84');break;case'hint':modal('Mở gợi ý cho câu hỏi này?','<p>Điểm tối đa của câu hỏi giảm từ 100 xuống 90 EXP. Cấp bậc của bạn được giữ nguyên.</p>','Mở gợi ý',()=>{state.hint=true;render()});break;case'terminal':$('#terminal-output').textContent=state.scenario==='offline'?'Mất kết nối mô phỏng. Không gửi lệnh.':!state.running?'Máy đã dừng. Hãy khởi chạy trước.':'student@cyberforce:~$ curl -I http://100.64.12.84\n\nHTTP/1.1 200 OK\nContent-Type: text/html\n\nPhản hồi mẫu. Không có yêu cầu mạng nào được gửi.\n\nstudent@cyberforce:~$';break;case'new':edit(-1);break;case'locked':modal('Điều kiện mở phòng','<p>Hoàn thành đủ 6 nhiệm vụ của SQL Injection căn bản trước khi học Blind SQL Injection.</p>','Về bài đang học',()=>location.hash='room');break;default:modal('Nội dung ngoài phạm vi prototype','<p>Màn hình này được mô tả trong bộ wireframe. Bản prototype hiện có 4 màn hình đại diện để duyệt bố cục.</p>','Đóng',()=>{})}})}
$('.skip').onclick=e=>{e.preventDefault();$('#main').focus()};window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0)});render();
